sql.where:
(
  p.owner_id = #{ownerId}
  OR EXISTS (
    SELECT 1 FROM project_member pm
    WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
  )
)
AND p.deleted = 0

    AND g.project_id = #{filter.projectId}


    AND g.task_id = #{filter.taskId}


    AND g.status = #{filter.status}


    AND (
        t.title LIKE CONCAT('%', #{filter.keyword}, '%')
        OR g.commit_message LIKE CONCAT('%', #{filter.keyword}, '%')
        OR g.ticket LIKE CONCAT('%', #{filter.keyword}, '%')
        OR g.commit_sha LIKE CONCAT('%', #{filter.keyword}, '%')
    )


    AND g.started_at >= #{filter.from}


    AND g.started_at <= #{filter.to}

mapper.select:
SELECT 
FROM git_commit_record g
JOIN project p ON p.id = g.project_id
JOIN task t ON t.id = g.task_id
JOIN app_user u ON u.id = g.operator_id
WHERE g.task_id = #{taskId}
  AND (
      p.owner_id = #{ownerId}
      OR EXISTS (
          SELECT 1 FROM project_member pm
          WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
      )
  )
  AND p.deleted = 0
ORDER BY g.started_at DESC, g.id DESC

SELECT ,
       g.repository_path, g.base_ref, g.file_paths_json,
       g.output_summary
FROM git_commit_record g
JOIN project p ON p.id = g.project_id
JOIN task t ON t.id = g.task_id
JOIN app_user u ON u.id = g.operator_id
WHERE g.id = #{id}
  AND (
      p.owner_id = #{ownerId}
      OR EXISTS (
          SELECT 1 FROM project_member pm
          WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
      )
  )
  AND p.deleted = 0
